setup.src/parse-port.ts:
export const parsePort = (raw: string): number | null => {
  if (raw.trim() === "") return null;
  const n = Number(raw);
  return Number.isInteger(n) && n > 0 && n <= 65535 ? n : null;
};

setup.src/parse-host.ts:
export const parseHost = (raw: string): string => {
  if (raw.trim() === "") throw new Error("host cannot be empty");
  return raw.trim().toLowerCase();
};

setup.src/parse-origin.ts:
export const parseOrigin = (raw: string): string => {
  return raw.trim().toLowerCase();
};

setup.src/parse-url.ts:
export const parseEndpoint = (raw: string): string => {
  return raw.trim();
};

setup.src/connect.ts:
import { parseHost } from "./parse-host";
import { parseOrigin } from "./parse-origin";
import { parsePort } from "./parse-port";
import { parseEndpoint } from "./parse-url";

export const buildTarget = (
  host: string,
  origin: string,
  endpoint: string,
  rawPort = "",
): { readonly host: string; readonly origin: string; readonly endpoint: string; readonly port: number } => ({
  host: parseHost(host),
  origin: parseOrigin(origin),
  endpoint: parseEndpoint(endpoint),
  port: parsePort(rawPort) ?? 443,
});

